<template>
  <section class="flex flex-col gap-6">
    <PageTitle title="Import Staffing Resources" />
    <Card class="max-w-lg w-full mx-auto">
      <CardContent class="flex flex-col gap-6 pt-6">
        <KitFormFileUpload
          form-id="staffing-contacts-import-file"
          :file-types="['.csv']"
          :file-size-limit="50"
          size-unit="MB"
          @on-process-data="onFileUploaded"
        />
        <Button :disabled="!s3Url || isSubmitting" :loading="isSubmitting" @click="submitImport"> Import </Button>
      </CardContent>
    </Card>
  </section>
</template>

<script setup lang="ts">
import { uploadStaffingContactFile } from '~/client';

definePageMeta({
  roles: ['admin', 'manager'],
  skipNavJourney: true,
});

useHead({
  title: 'Import Staffing Resources',
});

const s3Url = ref('');
const fileName = ref('');
const isSubmitting = ref(false);

function onFileUploaded(data: { privateUrl: string; publicUrl: string; fileName: string } | null) {
  if (data) {
    s3Url.value = data.privateUrl;
    fileName.value = data.fileName;
  } else {
    s3Url.value = '';
    fileName.value = '';
  }
}

async function submitImport() {
  if (!s3Url.value) return;

  isSubmitting.value = true;
  try {
    const response = await uploadStaffingContactFile({
      composable: '$fetch',
      body: {
        s3_url: s3Url.value,
        file_name: fileName.value,
      },
    });

    await navigateTo({
      name: 'staffing-resources-import-id',
      params: { id: response.id },
    });
  } catch (error) {
    console.error('Failed to start import:', error);
    showToastError('Failed to start import');
  } finally {
    isSubmitting.value = false;
  }
}
</script>
